from dataclasses import dataclass, replace

@dataclass(frozen=True)
class Op:
    kind: str       # "ins" or "del"
    pos: int
    text: str = ""  # inserted text
    n: int = 0      # chars deleted
    site: str = ""  # client id: breaks ties so every replica decides the same way

def transform(op: Op, prior: Op) -> Op:
    """Shift `op` so it applies after `prior`; both were made from the same rev."""
    if prior.kind == "ins":
        if prior.pos < op.pos or (prior.pos == op.pos and prior.site < op.site):
            return replace(op, pos=op.pos + len(prior.text))
        return op
    if prior.pos + prior.n <= op.pos:     # deletion entirely before op
        return replace(op, pos=op.pos - prior.n)
    if prior.pos >= op.pos:               # deletion after op: unaffected
        return op
    return replace(op, pos=prior.pos)     # op inside the deleted range (overlap cases elided)

class DocSession:                         # one per doc_id, pinned to one server
    def __init__(self, log):
        self.log = log                    # durable, append-only; rev = len(log)

    def submit(self, base_rev: int, op: Op) -> int:
        for prior in self.log[base_rev:]: # every op this client hadn't seen
            op = transform(op, prior)
        self.log.append(op)               # durable append BEFORE the ack
        broadcast(rev=len(self.log), op=op)
        return len(self.log)              # ack: the client's op is now this rev
